action.script:

import com.liferay.object.model.ObjectDefinition;
import com.liferay.object.model.ObjectEntry;
import com.liferay.object.service.ObjectDefinitionLocalServiceUtil;
import com.liferay.object.service.ObjectEntryLocalServiceUtil;
import com.liferay.portal.kernel.service.UserLocalServiceUtil;
import com.liferay.portal.kernel.util.GetterUtil;
import com.liferay.portal.kernel.workflow.WorkflowConstants;
import com.liferay.portal.kernel.workflow.WorkflowStatusManagerUtil;

import java.io.Serializable;

import java.util.Map;

long classPK = GetterUtil.getLong((String) workflowContext.get(
WorkflowConstants.CONTEXT_ENTRY_CLASS_PK));

ObjectEntry currentObjectEntry = ObjectEntryLocalServiceUtil.getObjectEntry(classPK);

Map < String, Serializable > currentObjectEntryValues = currentObjectEntry.getValues();

if(currentObjectEntryValues.organizationStatus == null){
	currentObjectEntryValues.put("organizationStatus", "awaitingApprovalOnEvp");

	ObjectEntryLocalServiceUtil.updateObjectEntry(serviceContext.getUserId(), classPK, currentObjectEntryValues, serviceContext);
}
